	proxy.conn.request(proxy.id, 7, []wayland.ArgValue{})!
}

// Set the actions available for this text input. Values set with this
// request are double-buffered. They will get applied on the next
// zwp_text_input_v3.commit request. If the available_actions array contains
// the none action, or contains the same action multiple times, the
// compositor must raise the invalid_action protocol error. Initially, no
// actions are available.
pub fn (proxy &ZwpTextInputV3) set_available_actions(available_actions []u8) ! {
	proxy.conn.request(proxy.id, 8, [wayland.ArgValue(available_actions)])!
}

// Requests an input panel to be shown (e.g. a on-screen keyboard). This
// request only hints the desired interaction pattern from the client side,
// and its effect may be ignored by compositors given other environmental
// factors. Repeated calls will be ignored.
pub fn (proxy &ZwpTextInputV3) show_input_panel() ! {
	proxy.conn.request(proxy.id, 9, []wayland.ArgValue{})!
}

// Requests an input panel to be hidden. This request only hints the desired
// interaction pattern from the client side, and its effect may be ignored by
// compositors given other environmental factors. Repeated calls will be
// ignored.
pub fn (proxy &ZwpTextInputV3) hide_input_panel() ! {
	proxy.conn.request(proxy.id, 10, []wayland.ArgValue{})!
}

