// zwp_text_input_manager_v3

// zwp_text_input_manager_v3_desc is the wire description of zwp_text_input_manager_v3.
pub const zwp_text_input_manager_v3_desc = wayland.IfaceDesc{
	name:     'zwp_text_input_manager_v3'
	version:  2
	requests: [
		wayland.MsgDesc{
			name:       'destroy'
			opcode:     0
			destructor: true
		},
		wayland.MsgDesc{
			name:   'get_text_input'
			opcode: 1
			args:   [
				wayland.ArgDesc{
					name:  'id'
					kind:  .new_id
					iface: 'zwp_text_input_v3'
				},
				wayland.ArgDesc{
					name:  'seat'
					kind:  .obj
					iface: 'wl_seat'
				},
			]
		},
	]
}

// ZwpTextInputManagerV3 is a client side proxy for zwp_text_input_manager_v3.
// A factory for text-input objects. This object is a global singleton.
pub struct ZwpTextInputManagerV3 {
	wayland.Object
}

// zwp_text_input_manager_v3_proxy wraps an object id in a ZwpTextInputManagerV3 proxy.
pub fn zwp_text_input_manager_v3_proxy(conn &wayland.Connection, id u32) ZwpTextInputManagerV3 {
	return ZwpTextInputManagerV3{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'zwp_text_input_manager_v3'
		}
	}
}

// Destroy the wp_text_input_manager object.
pub fn (proxy &ZwpTextInputManagerV3) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// Creates a new text-input object for a given seat.
pub fn (proxy &ZwpTextInputManagerV3) get_text_input(seat wl.WlSeat) !ZwpTextInputV3 {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'zwp_text_input_v3'
	}
	proxy.conn.register_object(id_id, 'zwp_text_input_v3', &zwp_text_input_v3_desc)!
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(wayland.ObjectRef{ id: id_id }),
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id })])!
	return ZwpTextInputV3{
		Object: id_object
	}
}

// bind_zwp_text_input_manager_v3 binds the zwp_text_input_manager_v3 global to a typed proxy.
pub fn bind_zwp_text_input_manager_v3(conn &wayland.Connection, global wayland.Global) !ZwpTextInputManagerV3 {
	version := if global.version < zwp_text_input_manager_v3_desc.version {
		global.version
	} else {
		zwp_text_input_manager_v3_desc.version
	}
	object := conn.bind_global(global, 'zwp_text_input_manager_v3', version, &zwp_text_input_manager_v3_desc)!
	return ZwpTextInputManagerV3{
		Object: object
	}
}
